SELECT u.email, (lower(u.email) LIKE '%@' || d.valor) AS dominio_ok, (lower(u.email) LIKE '%@' || d.valor AND lower(u.email) = a.valor) AS admin, e.id AS executivo_id, e.nome AS executivo FROM INT_USER u CROSS JOIN (SELECT valor FROM configuracao WHERE chave = 'dominio') d CROSS JOIN (SELECT valor FROM configuracao WHERE chave = 'admin_email') a LEFT JOIN executivos e ON lower(e.email) = lower(u.email) AND e.ativo AND lower(u.email) LIKE '%@' || d.valor WHERE u.user_id = CAST(:VAR_USER AS UUID) AND u.enabled
